import{_ as s,o as a,c as t,a0 as i}from"./chunks/framework.BxCN1dRw.js";const k=JSON.parse('{"title":"组合与移除参考业务","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/example-removal"},"headers":[],"relativePath":"tutorials/example-removal.md","filePath":"tutorials/example-removal.md"}'),o={name:"tutorials/example-removal.md"};function d(r,e,n,p,c,l){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="组合与移除参考业务" tabindex="-1">组合与移除参考业务 <a class="header-anchor" href="#组合与移除参考业务" aria-label="Permalink to &quot;组合与移除参考业务&quot;">​</a></h1><p>模板自带两个参考业务：知识库（完整业务）与便签（只为验证组合接口的最小示例）。本章回答&quot;这个模板怎么变成我的产品&quot;：先看清示例拥有什么，再预览移除、删除<strong>任意一个</strong>、或一路移除到零示例——源码、路由、迁移登记、任务、教程导航一起消失，而 Core（注册/登录、成员、文件服务、任务、通知、API Key、审计、邮件、限流、遥测）原样保留并继续可验证。前端接入与四种应用组合的运行方式见<a href="./add-example">接入一个参考业务</a>；本章专注移除侧的工具、保护与边界。</p><h2 id="_1-所有权清单-示例到底拥有什么" tabindex="-1">1. 所有权清单：示例到底拥有什么 <a class="header-anchor" href="#_1-所有权清单-示例到底拥有什么" aria-label="Permalink to &quot;1. 所有权清单：示例到底拥有什么&quot;">​</a></h2><p>每个示例在 <code>examples/&lt;id&gt;/manifest.json</code> 登记五类信息，每类都有检查器钉住。以<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">知识库</a>与<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/examples/notes/manifest.json" target="_blank" rel="noreferrer">便签</a>为例：</p><table tabindex="0"><thead><tr><th>登记项</th><th>内容</th><th>谁在检查</th></tr></thead><tbody><tr><td><code>ownedPaths</code></td><td>示例整删的后端模块、Views、迁移、测试、E2E、教程页与研究文档</td><td><code>pnpm boundaries:check</code>、清单测试</td></tr><tr><td><code>registrationMarkers</code></td><td>组装点文件里的 <code>example:&lt;前缀&gt;:*:start/end</code> 注册区块</td><td>同上，成对且有序才通过</td></tr><tr><td><code>compositionPoints</code></td><td>API/Worker/Web/文档导航等需要改动（而非删除）的文件</td><td>存在性检查</td></tr><tr><td><code>ownedDependencies</code></td><td>只有示例在用的 npm 依赖（如 react-markdown）</td><td>移除时从对应 package.json 剥离</td></tr><tr><td><code>ownedCargoDependencies</code></td><td>只有示例在用的 Rust 依赖（zip、pulldown-cmark）</td><td>移除时从对应 Cargo.toml 剥离</td></tr></tbody></table><p>独占性是硬约束：两个示例声明同一条 <code>ownedPaths</code>，或声明同一份清单里的同一个独占依赖，都属于所有权冲突，删除工具无法裁决，验证处直接失败并列出冲突双方；移除命令在动第一个字节之前就运行同一验证。反向约束同样成文：Core 模块（含后加入的邮件与 telemetry）<strong>不 import 任何示例</strong>，示例之间也不得互相引用（包括经由共享 views 桶文件绕道）——<code>boundaries:check</code> 逐文件扫描 import 方向、SQL 字符串里的表归属与跨模块 Views 引用，把示例写进 Identity 这类捷径会在检查器处直接失败。每个模块的 <code>module.json</code> 声明自己的表（如 <code>knowledge.documents</code>），迁移里出现的每张表都必须有主人。</p><h2 id="_2-dry-run-先看清楚会发生什么" tabindex="-1">2. dry-run：先看清楚会发生什么 <a class="header-anchor" href="#_2-dry-run-先看清楚会发生什么" aria-label="Permalink to &quot;2. dry-run：先看清楚会发生什么&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example-remove</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # 默认移除知识库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/example-remove.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 或者移除便签</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/scripts/example-remove.mjs" target="_blank" rel="noreferrer">移除工具</a>列出将要删除的每一条路径、将移除的每个标记区块、导航里将消失的教程页、将剥离的依赖，以及之后要重跑的再生命令——<strong>不写任何文件</strong>。示例 id 用 <code>--example &lt;id&gt;</code> 显式选择；id 不存在时工具直接报错并列出当前注册的全部 id，不会默默作用于&quot;最像的那个&quot;。</p><p>保护是硬性的，拒绝时你得到的是清单而不是覆盖：检测到未提交改动，它列出脏文件并拒绝执行、一个字节都不动；某个登记标记区块被改得不再成对（start/end 各恰好一次），同样拒绝并列出位置。工具只面向干净的 git 工作副本工作——这份谨慎同样保护你对模板的定制：先提交或丢弃自己的改动，或手工解开与示例纠缠的部分。</p><h2 id="_3-移除任意一个-或一路移除到零" tabindex="-1">3. 移除任意一个，或一路移除到零 <a class="header-anchor" href="#_3-移除任意一个-或一路移除到零" aria-label="Permalink to &quot;3. 移除任意一个，或一路移除到零&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example-remove</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                              # 移除知识库 → 仅剩便签</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/example-remove.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 移除便签 → 仅剩知识库</span></span></code></pre></div><p>工具按清单精确执行：删除示例拥有的路径，移除组装点里的标记区块（<code>apps/api/src/lib.rs</code> 的路由与 OpenAPI 注册、<code>apps/worker/src/main.rs</code> 的任务注册、Web 路由与视图导出、教程导航），从 <code>docs/site.json</code> 摘掉示例教程页，剥离示例独占依赖，把清单置为 <code>status: removed</code>（清单本身保留——desktop-smoke 等脚本按它自适应），最后原地重新生成派生产物：<code>pnpm install</code>、<code>cargo update --workspace</code>、<code>pnpm generate</code>（OpenAPI/contracts/SDK）、项目文档引用。</p><p>要移除多个示例，请<strong>逐个执行并在两次移除之间提交一次副本改动</strong>——工具只改干净的副本，这也是它保护你的方式。移除全部示例后只剩 Core，登录回到通用首页；如果删除的是声明默认入口的示例（今天是知识库的「我的文档」），登录着陆同样自然回到通用首页，不存在指向已删页面的入口。每次移除结束后用同一组门禁验收：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-core</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # fmt、clippy、后端测试、contracts 漂移、边界检查</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs-build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 文档站构建，死链会在这里暴露</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:frontend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @saas/web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span></code></pre></div><p>迁移历史有两条路径，工具默认走<strong>保守</strong>的那条：</p><ul><li><strong>已运行过或发布过迁移的项目</strong>：什么都不做。示例拥有的迁移原样保留，<code>_sqlx_migrations</code> 历史完整——源码移除绝不等于删除已有业务数据，这些迁移描述的表留在数据库里，直到你用<strong>新增迁移</strong>显式处理它们。保留路径同时把这些文件登记进清单的 <code>retainedMigrations</code>：它们的表已经没有代码主人，表归属检查器据此豁免这几个历史文件，而&quot;每张表必须有主人&quot;的规则对其余一切照旧生效。</li><li><strong>全新项目（还没有任何数据库）</strong>：<code>just example-remove --trim-migrations</code> 裁掉示例迁移，新空库从 Core 迁移直接初始化。裁剪只对&quot;从未应用过这些迁移&quot;的副本合法；CI 的删例验收走的就是这条路径，在一个真正的空库上验证。</li></ul><h2 id="_4-移除后-core-还剩什么、什么退场" tabindex="-1">4. 移除后 Core 还剩什么、什么退场 <a class="header-anchor" href="#_4-移除后-core-还剩什么、什么退场" aria-label="Permalink to &quot;4. 移除后 Core 还剩什么、什么退场&quot;">​</a></h2><p>注册/登录与会话、企业成员、文件服务与对象清理、任务与恢复、通知、API Key、审计、密码重置邮件、限流、遥测——全部保留，且有测试钉着：删例后的 <code>just check-core</code> 跑的就是这些幸存测试（<code>registration</code>、<code>members</code>、<code>jobs</code>、<code>config</code>、<code>migration</code>）。邮件与 telemetry 模块不在任何 <code>ownedPath</code> 中，这是手递说明里点名的验收点。</p><p>历史记录不随源码消失：指向已删业务的历史通知显示&quot;此通知的功能当前不可用&quot;，不再是可点击的目标；旧书签与外部深链接落在&quot;相关功能当前不可用&quot;页面，页面提供返回首页的出口，地址不被悄悄改写。生产工具分层清楚：<code>production-backup</code> 与 <code>production-restore</code> 与业务无关（它们只认数据库与对象清单），删例后照常可用；<code>production-smoke</code> 与 <code>production-restore-drill</code> 的种子旅程以示例数据为载体，删例后它们会诚实说明并退出，提示你按同样的骨架为自己的业务写演练——备份数据平面没有变，变的只是旅程。</p><p>性能预算按同一条线分层：注册预算（<code>perf_registration.rs</code>）属于 Core，删例后继续被后端测试钉住；文档列表、创建与导出的预算（<code>perf_documents.rs</code>）和查询计划脚本里的示例列表 SQL 以示例为载体退场——<code>just perf</code> 里的测试选择要换成你自己业务的性能测试，<code>just perf-ci</code> 里的查询计划脚本会诚实说明并退出。</p><p>CI 在每个 PR 上做真实演练：把模板克隆到临时副本，制造脏文件验证保护拒绝；在第一个副本实际执行 <code>--trim-migrations</code> 移除知识库，得到仅便签组合并过整组门禁，随后在同一副本再移除便签得到仅 Core 组合并复跑前端门禁；在第二个副本移除便签得到仅知识库组合，同样过整组门禁。加上未经移除的主源码（双示例，由 <code>verify</code> job 完整验证），四种组合各自完成构建与测试——最后执行下一节的接入练习。</p><h2 id="_5-接入你自己的业务" tabindex="-1">5. 接入你自己的业务 <a class="header-anchor" href="#_5-接入你自己的业务" aria-label="Permalink to &quot;5. 接入你自己的业务&quot;">​</a></h2><p>删除示例只是开始，教程的承诺是&quot;新业务沿同一套公开接口接入&quot;。前端页面与导航的接入方式见<a href="./add-example">接入一个参考业务</a>；后端沿以下步骤：</p><ol><li><strong>自己的模型与迁移</strong>：新建 <code>migrations/00XX_&lt;业务&gt;.sql</code>，<code>CREATE SCHEMA</code> 建自己的表，<code>module.json</code> 登记表归属（<code>boundaries:check</code> 要求每张表有主人；引用 <code>saas_core.users(id)</code> 这类 Core 稳定标识是允许的跨模块引用）。</li><li><strong>实现模块</strong>：在 <code>crates/app/src/modules/mod.rs</code> 声明模块，在 <code>crates/app/src/modules/&lt;业务&gt;/</code> 里写 HTTP handler（用 <code>identity::require_session</code> 取当前用户）与领域查询；模块不碰其他模块的私有表。标识符保持字符串、在 SQL 边界显式转换（<code>$1::uuid</code>、<code>RETURNING id::text</code>）——workspace 的 sqlx 不开 uuid 编解码 feature。</li><li><strong>注册路由与 OpenAPI</strong>：在 <code>apps/api/src/lib.rs</code> 的组装点把模块 router 并入 <code>domain_routes</code>、把 openapi() 并入文档。</li><li><strong>生成 SDK</strong>：<code>pnpm generate</code> 让 contracts/SDK 出现你的资源类型。</li><li><strong>测试</strong>：像 <code>apps/api/tests/notes.rs</code> 那样在公开 HTTP 接口上断言注册 → 创建 → 读取（<code>#[sqlx::test]</code> 需要一个 PostgreSQL，<code>just test-backend</code> 会自备一次性实例）。</li></ol><p>练习脚本（<code>scripts/example-new-business.mjs</code>）替你把这些文件写进临时副本，借助<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/scripts/lib/postgres.mjs" target="_blank" rel="noreferrer">同一条测试 postgres 通道</a>跑 <code>cargo test</code> 与 clippy——CI 绿灯就是&quot;删例后接入路径可用&quot;的可执行证据。</p><h2 id="_6-运行本章检查" tabindex="-1">6. 运行本章检查 <a class="header-anchor" href="#_6-运行本章检查" aria-label="Permalink to &quot;6. 运行本章检查&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/example-remove.test.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example-remove</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>清单与工作副本之间的漂移由两层钉住：<code>boundaries:check</code> 在每次 <code>just check</code> 里验证登记路径、独占性与标记区块，<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/tests/tooling/example-remove.test.mjs" target="_blank" rel="noreferrer">清单工具测试</a>在合成副本上验证移除语义本身——dry-run 零写入、精确删除与标记编辑、未知 id 与所有权冲突的拒绝、导航裁剪、依赖剥离、迁移默认保留与 <code>--trim-migrations</code>、脏副本与结构破坏的拒绝。真正的删例验收在 CI 的 <code>example-removal</code> job 里对全新副本完整执行。</p><hr><p>源码版本：<code>d209def654c8</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/docs/tutorials/23-example-removal.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,31)])])}const g=s(o,[["render",d]]);export{k as __pageData,g as default};
